import type { SystemRow, NativeResult } from "./beszel-types";
import { Alert, Button, Group, Stack, Text } from "@mantine/core";
import { useWidgetHost, useWidgetQuery, useWidgetServices, useWidgetState } from "@homarr/widget-sdk";
import "./rack.css";
export default function Rack() {
  const host = useWidgetHost();
  const services = useWidgetServices();
  const query = useWidgetQuery<NativeResult<SystemRow[]>>("systems", {}, {refetchInterval: 15000});
  const [selected, setSelected] = useWidgetState("selected", "");
  const systems = query.data?.data ?? [];
  const rows = host.displayMode === "advanced" ? systems : systems.slice(0, 8);
  const inspect = (system:SystemRow) => { setSelected(system.id); services.openDetail({title: system.name, content: <Stack><Text>{system.hostname} · {system.osName}</Text><Text>CPU: {system.cpu.toFixed(1)}% · Memory: {system.memory.toFixed(1)}% · Disk: {system.disk.toFixed(1)}%</Text><Text>{system.cpuModel} · {system.cores} cores</Text><Text>Uptime: {Math.floor(system.uptime / 3600)} hours</Text></Stack>}); };
  return <Stack className="reference-rack" p="sm" h="100%" style={{overflow:"auto"}}>
    <Group justify="space-between"><Text fw={600}>Server rack</Text><Text size="xs" c="dimmed">{systems.length} systems</Text></Group>
    {query.error && <Alert color="red">{query.error.message}<Button size="xs" variant="subtle" onClick={() => void query.refetch()}>Retry</Button></Alert>}
    <svg viewBox={`0 0 420 ${Math.max(90, rows.length * 64 + 24)}`} role="group" aria-label="Beszel server rack" style={{width:"100%", flexShrink:0}}>
      <rect x="1" y="1" width="418" height={Math.max(88, rows.length * 64 + 22)} rx="8" fill="var(--mantine-color-default)" stroke="var(--mantine-color-default-border)" />
      {rows.map((system, index) => <g key={system.id} role="button" tabIndex={0} aria-label={`Inspect ${system.name}, ${system.status}`} onClick={() => inspect(system)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); inspect(system); } }} className="reference-rack__unit">
        <rect x="14" y={12 + index * 64} width="392" height="54" rx="4" fill="var(--mantine-color-body)" stroke={selected === system.id ? "var(--mantine-color-blue-6)" : "var(--mantine-color-default-border)"} />
        <circle cx="31" cy={39 + index * 64} r="5" fill={system.status === "up" ? "var(--mantine-color-teal-6)" : "var(--mantine-color-red-6)"} />
        <text x="47" y={34 + index * 64} fill="var(--mantine-color-text)" fontSize="14">{system.name.slice(0, 35)}</text>
        <text x="47" y={53 + index * 64} fill="var(--mantine-color-dimmed)" fontSize="11">CPU {system.cpu.toFixed(1)}% · RAM {system.memory.toFixed(1)}% · {system.status}</text>
        <rect x="345" y={26 + index * 64} width="44" height="24" rx="3" fill="var(--mantine-color-dark-5)" />
        {[0,1,2,3].map((slot) => <path key={slot} d={`M${350 + slot * 10},${30 + index * 64}v16`} stroke="var(--mantine-color-gray-6)" />)}
      </g>)}
    </svg>
    {!query.isPending && !query.error && !systems.length && <Text c="dimmed">No Beszel systems are available.</Text>}
  </Stack>;
}

